NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: 'In mense octavo in anno secundo Darii regis, factum est verbum Domini ad Zachariam, filium Barachiae filii Addo, prophetam, dicens:',
        2: 'Iratus est Dominus super patres vestros iracundia.',
        3: 'Et dices ad eos: Haec dicit Dominus exercituum: Convertimini ad me, ait Dominus exercituum: et convertar ad vos, dicit Dominus exercituum.',
        4: 'Ne sitis sicut patres vestri, ad quos clamabant prophetae priores, dicentes: Haec dicit Dominus exercituum: Convertimini de viis vestris malis, et de cogitationibus vestris pessimis: et non audierunt, neque attenderunt ad me, dicit Dominus.',
        5: 'Patres vestri ubi sunt? et prophetae numquid in sempiternum vivent?',
        6: 'Verumtamen verba mea, et legitima mea, quae mandavi servis meis prophetis, numquid non comprehenderunt patres vestros, et conversi sunt, et dixerunt: Sicut cogitavit Dominus exercituum facere nobis secundum vias nostras, et secundum adinventiones nostras fecit nobis.',
        7: 'In die vigesima et quarta undecimi mensis Sabath, in anno secundo Darii, factum est verbum Domini ad Zachariam filium Barachiae, filii Addo, prophetam, dicens:',
        8: 'Vidi per noctem, et ecce vir ascendens super equum rufum, et ipse stabat inter myrteta, quae erant in profundo: et post eum equi rufi, varii, et albi.',
        9: 'Et dixi: Quid sunt isti, domine mi? Et dixit ad me Angelus, qui loquebatur in me: Ego ostendam tibi quid sint haec.',
        10: 'Et respondit vir, qui stabat inter myrteta, et dixit: Isti sunt, quos misit Dominus ut perambulent terram.',
        11: 'Et responderunt Angelo Domini, qui stabat inter myrteta, et dixerunt: Perambulavimus terram, et ecce omnis terra habitatur, et quiescit.',
        12: 'Et respondit angelus Domini, et dixit: Domine exercituum usquequo tu non misereberis Ierusalem, et urbium Iuda, quibus iratus es? iste iam septuagesimus annus est.',
        13: 'Et respondit Dominus angelo, qui loquebatur in me verba bona, verba consolatoria.',
        14: 'Et dixit ad me angelus, qui loquebatur in me: Clama, dicens: Haec dicit Dominus exercituum: Zelatus sum Ierusalem, et Sion zelo magno.',
        15: 'Et ira magna ego irascor super gentes opulentas: quia ego iratus sum parum, ipsae vero adiuverunt in malum.',
        16: 'Propterea haec dicit Dominus: Revertar ad Ierusalem in misericordiis: et domus mea aedificabitur in ea, ait Dominus exercituum: et perpendiculum extendetur super Ierusalem.',
        17: 'Adhuc, clama dicens: Haec dicit Dominus exercituum: Adhuc affluent civitates meae bonis: et consolabitur adhuc Dominus Sion, et eliget adhuc Ierusalem.',
        18: 'Et levavi oculos meos, et vidi: et ecce quattuor cornua.',
        19: 'Et dixi ad angelum, qui loquebatur in me: Quid sunt haec? Et dixit ad me: Haec sunt cornua, quae ventilaverunt Iuda, et Israel, et Ierusalem.',
        20: 'Et ostendit mihi Dominus quattuor fabros.',
        21: 'Et dixi: Quid isti veniunt facere? Qui ait, dicens: Haec sunt cornua, quae ventilaverunt Iuda per singulos viros, et nemo eorum levavit caput suum: et venerunt isti deterrere ea, ut deiiciant cornua gentium, quae levaverunt cornu super terram Iuda ut dispergerent eam.',
    },
    2: {
        1: 'Et levavi oculos meos, et vidi: et ecce vir, et in manu eius funiculus mensorum.',
        2: 'Et dixi: Quo tu vadis? Et dixit ad me: Ut metiar Ierusalem, et videam quanta sit latitudo eius, et quanta longitudo eius.',
        3: 'Et ecce angelus, qui loquebatur in me, egrediebatur, et angelus alius egrediebatur in occursum eius.',
        4: 'Et dixit ad eum: Curre, loquere ad puerum istum, dicens: Absque muro habitabitur Ierusalem prae multitudine hominum, et iumentorum in medio eius.',
        5: 'Et ego ero ei, ait Dominus, murus ignis in circuitu: et in gloria ero in medio eius.',
        6: 'O, o fugite de terra Aquilonis, dicit Dominus: quoniam in quattuor ventos caeli dispersi vos, dicit Dominus.',
        7: 'O Sion, fuge quae habitas apud filiam Babylonis:',
        8: 'quia haec dicit Dominus exercituum: Post gloriam misit me ad gentes, quae spoliaverunt vos: qui enim tetigerit vos, tangit pupillam oculi mei:',
        9: 'quia ecce ego levo manum meam super eos, et erunt praedae his, qui serviebant sibi: et cognoscetis quia Dominus exercituum misit me.',
        10: 'Lauda, et laetare filia Sion: quia ecce ego venio, et habitabo in medio tui, ait Dominus.',
        11: 'Et applicabuntur Gentes multae ad Dominum in die illa, et erunt mihi in populum, et habitabo in medio tui: et scies quia Dominus exercituum misit me ad te.',
        12: 'Et possidebit Dominus Iuda partem suam in terra sanctificata: et eliget adhuc Ierusalem.',
        13: 'Sileat omnis caro a facie Domini: quia consurrexit de habitaculo sancto suo.',
    },
    3: {
        1: 'Et ostendit mihi Dominus Iesum sacerdotem magnum stantem coram angelo Domini: et satan stabat a dextris eius ut adversaretur ei.',
        2: 'Et dixit Dominus ad satan: Increpet Dominus te Satan: et increpet Dominus te, qui elegit Ierusalem! numquid non iste torris est erutus de igne?',
        3: 'Et Iesus erat indutus vestibus sordidis: et stabat ante faciem angeli.',
        4: 'Qui respondit, et ait ad eos, qui stabant coram se, dicens: Auferte vestimenta sordida ab eo. Et dixit ad eum: Ecce abstuli a te iniquitatem tuam, et indui te mutatoriis.',
        5: 'Et dixit: Ponite cidarim mundam super caput eius. Et posuerunt cidarim mundam super caput eius, et induerunt eum vestibus: et angelus Domini stabat.',
        6: 'Et contestabatur angelus Domini Iesum, dicens:',
        7: 'Haec dicit Dominus exercituum: Si in viis meis ambulaveris, et custodiam meam custodieris: tu quoque iudicabis domum meam, et custodies atria mea, et dabo tibi ambulantes de his, qui nunc hic assistunt.',
        8: 'Audi Iesu sacerdos magne, tu et amici tui, qui habitant coram te, quia viri portendentes sunt. ecce enim ego ADDUCAM SERVUM MEUM ORIENTEM.',
        9: 'Quia ecce lapis, quem dedi coram Iesu: super lapidem unum septem oculi sunt: ecce ego celabo sculpturam eius, ait Dominus exercituum: et auferam iniquitatem terrae illius in die una.',
        10: 'In die illa, dicit Dominus exercituum, vocabit vir amicum suum subter vitem, et subter ficum.',
    },
    4: {
        1: 'Et reversus est angelus, qui loquebatur in me, et suscitavit me, quasi virum, qui suscitatur de somno suo.',
        2: 'Et dixit ad me: Quid tu vides? Et dixi: Vidi, et ecce candelabrum aureum totum, et lampas eius super caput ipsius, et septem lucernae eius super illud: et septem infusoria lucernis, quae erant super caput eius.',
        3: 'Et duae olivae super illud: una a dextris lampadis, et una a sinistris eius.',
        4: 'Et respondi, et aio ad angelum, qui loquebatur in me, dicens: Quid sunt haec, domine mi?',
        5: 'Et respondit angelus, qui loquebatur in me, et dixit ad me: Numquid nescis quid sunt haec? Et dixi: Non, domine mi.',
        6: 'Et respondit, et ait ad me, dicens: Hoc est verbum Domini ad Zorobabel, dicens: Non in exercitu, nec in robore, sed in spiritu meo, dicit Dominus exercituum.',
        7: 'Quis tu mons magne coram Zorobabel? in planum: et educet lapidem primarium, et exaequabit gratiam gratiae eius.',
        8: 'Et factum est verbum Domini ad me, dicens:',
        9: 'Manus Zorobabel fundaverunt domum istam, et manus eius perficient eam: et scietis quia Dominus exercituum misit me ad vos.',
        10: 'Quis enim despexit dies parvos? et laetabuntur, et videbunt lapidem stanneum in manu Zorobabel. Septem isti oculi sunt Domini, qui discurrunt in universam terram.',
        11: 'Et respondi, et dixi ad eum: Quid sunt duae olivae istae ad dexteram candelabri, et ad sinistram eius?',
        12: 'Et respondi secundo, et dixi ad eum: Quid sunt duae spicae olivarum, quae sunt iuxta duo rostra aurea, in quibus sunt suffusoria ex auro?',
        13: 'Et ait ad me, dicens: Numquid nescis quid sunt haec? Et dixi: Non, domine mi.',
        14: 'Et dixit: Isti sunt duo filii olei, qui assistunt Dominatori universae terrae.',
    },
    5: {
        1: 'Et conversus sum, et levavi oculos meos: et vidi, et ecce volumen volans.',
        2: 'Et dixit ad me: Quid tu vides? Et dixi: Ego video volumen volans: longitudo eius viginti cubitorum, et latitudo eius decem cubitorum.',
        3: 'Et dixit ad me: Haec est maledictio, quae egreditur super faciem omnis terrae: quia omnis fur, sicut ibi scriptum est, iudicabitur: et omnis iurans, ex hoc similiter iudicabitur.',
        4: 'Educam illud, dicit Dominus exercituum: et veniet ad domum furis, et ad domum iurantis in nomine meo mendaciter: et commorabitur in medio domus eius, et consumet eam, et ligna eius, et lapides eius.',
        5: 'Et egressus est angelus, qui loquebatur in me: et dixit ad me: Leva oculos tuos, et vide quid est hoc, quod egreditur.',
        6: 'Et dixi: Quidnam est? Et ait: Haec est amphora egrediens. Et dixit: Haec est oculus eorum in universa terra.',
        7: 'Et ecce talentum plumbi portabatur, et ecce mulier una sedens in medio amphorae.',
        8: 'Et dixit: Haec est impietas. Et proiecit eam in medio amphorae, et misit massam plumbeam in os eius.',
        9: 'Et levavi oculos meos, et vidi: et ecce duae mulieres egredientes, et spiritus in alis earum, et habebant alas quasi alas milvi: et levaverunt amphoram inter terram, et caelum.',
        10: 'Et dixi ad angelum, qui loquebatur in me: Quo istae deferunt amphoram?',
        11: 'Et dixit ad me: Ut aedificetur ei domus in terra Sennaar, et stabiliatur, et ponatur ibi super basem suam.',
    },
    6: {
        1: 'Et conversus sum, et levavi oculos meos, et vidi: et ecce quattuor quadrigae egredientes de medio duorum montium: et montes, montes aerei.',
        2: 'In quadriga prima equi rufi, et in quadriga secunda equi nigri,',
        3: 'et in quadriga tertia equi albi, et in quadriga quarta equi varii, et fortes.',
        4: 'Et respondi, et dixi ad angelum, qui loquebatur in me: Quid sunt haec, domine mi?',
        5: 'Et respondit angelus, et ait ad me: Isti sunt quattuor venti caeli, qui egrediuntur ut stent coram Dominatore omnis terrae.',
        6: 'In qua erant equi nigri, egrediebantur in terram Aquilonis: et albi egressi sunt post eos: et varii egressi sunt ad terram Austri.',
        7: 'Qui autem erant robustissimi, exierunt, et quaerebant ire, et discurrere per omnem terram. Et dixit: Ite, perambulate terram. et perambulaverunt terram.',
        8: 'Et vocavit me, et locutus est ad me, dicens: Ecce qui egrediuntur in terram Aquilonis, requiescere fecerunt spiritum meum in terra Aquilonis.',
        9: 'Et factum est verbum Domini ad me, dicens:',
        10: 'Sume a transmigratione ab Holdai, et a Tobia, et ab Idaia; et venies tu in die illa, et intrabis domum Iosiae, filii Sophoniae, qui venerunt de Babylone.',
        11: 'Et sumes aurum, et argentum: et facies coronas, et pones in capite Iesu filii Iosedech sacerdotis magni,',
        12: 'et loqueris ad eum, dicens: Haec ait Dominus exercituum, dicens: ECCE VIR ORIENS NOMEN EIUS: et subter eum orietur, et aedificabit templum Domino.',
        13: 'Et ipse extruet templum Domino: et ipse portabit gloriam, et sedebit, et dominabitur super solio suo: et erit sacerdos super solio suo, et consilium pacis erit inter illos duos.',
        14: 'Et coronae erunt Helem, et Tobiae, et Idaiae, et Hem, filio Sophoniae, memoriale in templo Domini.',
        15: 'Et qui procul sunt, venient, et aedificabunt in templo Domini: et scietis quia Dominus exercituum misit me ad vos. Erit autem hoc, si auditu audieritis vocem Domini Dei vestri.',
    },
    7: {
        1: 'Et factum est in anno quarto Darii regis, factum est verbum Domini ad Zachariam, in quarta mensis noni, qui est Casleu.',
        2: 'Et miserunt ad domum Dei Sarasar, et Rogommelech, et viri, qui erant cum eo ad deprecandam faciem Domini:',
        3: 'ut dicerent sacerdotibus domus Domini exercituum, et prophetis loquentes: numquid flendum est mihi in quinto mense, vel sanctificare me debeo, sicut iam feci multis annis?',
        4: 'Et factum est verbum Domini exercituum ad me, dicens:',
        5: 'Loquere ad omnem populum terrae, et ad sacerdotes, dicens: Cum ieiunaretis, et plangeretis in quinto et septimo per hos septuaginta annos: numquid ieiunium ieiunastis mihi?',
        6: 'et cum comedistis, et bibistis, numquid non vobis comedistis, et vobismetipsis bibistis?',
        7: 'Numquid non sunt verba, quae locutus est Dominus in manu prophetarum priorum, cum adhuc Ierusalem habitaretur, ut esset opulenta, ipsa et urbes in circuitu eius, et ad Austrum, et in campestribus habitaretur?',
        8: 'Et factum est verbum Domini ad Zachariam, dicens:',
        9: 'Haec ait Dominus exercituum, dicens: Iudicium verum iudicate, et misericordiam, et miserationes facite, unusquisque cum fratre suo.',
        10: 'Et viduam, et pupillum, et advenam, et pauperem nolite calumniari: et malum vir fratri suo non cogitet in corde suo.',
        11: 'Et noluerunt attendere, et averterunt scapulam recedentes, et aures suas aggravaverunt ne audirent.',
        12: 'Et cor suum posuerunt ut adamantem, ne audirent legem, et verba quae misit Dominus exercituum in spiritu suo per manum prophetarum priorum: et facta est indignatio magna a Domino exercituum.',
        13: 'Et factum est sicut locutus est, et non audierunt: sic clamabunt, et non exaudiam, dicit Dominus exercituum.',
        14: 'Et dispersi eos per omnia regna, quae nesciunt: et terra desolata est ab eis, eo quod non esset transiens et revertens: et posuerunt terram desiderabilem in desertum.',
    },
    8: {
        1: 'Et factum est verbum Domini exercituum, dicens:',
        2: 'Haec dicit Dominus exercituum: Zelatus sum Sion zelo magno, et indignatione magna zelatus sum eam.',
        3: 'Haec dicit Dominus exercituum: Reversus sum ad Sion, et habitabo in medio Ierusalem: et vocabitur Ierusalem Civitas veritatis, et Mons Domini exercituum mons sanctificatus.',
        4: 'Haec dicit Dominus exercituum: Adhuc habitabunt senes, et anus in plateis Ierusalem: et viri baculus in manu eius prae multitudine dierum.',
        5: 'Et plateae civitatis complebuntur infantibus, et puellis ludentibus in plateis eius.',
        6: 'Haec dicit Dominus exercituum: Si videbitur difficile in oculis reliquiarum populi huius in diebus illis, numquid in oculis meis difficile erit, dicit Dominus exercituum?',
        7: 'Haec dicit Dominus exercituum: Ecce ego salvabo populum meum de terra Orientis, et de terra Occasus solis.',
        8: 'Et adducam eos, et habitabunt in medio Ierusalem: et erunt mihi in populum, et ego ero eis in Deum in veritate, et in iustitia.',
        9: 'Haec dicit Dominus exercituum: Confortentur manus vestrae, qui auditis in his diebus sermones istos per os prophetarum in die, qua fundata est domus Domini exercituum, ut templum aedificaretur.',
        10: 'Siquidem ante dies illos merces hominum non erat, nec merces iumentorum erat, neque introeunti, neque exeunti erat pax prae tribulatione: et dimisi omnes homines, unumquemque contra proximum suum.',
        11: 'Nunc autem non iuxta dies priores ego faciam reliquiis populi huius, dicit Dominus exercituum,',
        12: 'sed semen pacis erit: vinea dabit fructum suum, et terra dabit germen suum, et caeli dabunt rorem suum: et possidere faciam reliquias populi huius universa haec.',
        13: 'Et erit: sicut eratis maledictio in Gentibus, domus Iuda, et domus Israel: sic salvabo vos, et eritis benedictio: nolite timere, confortentur manus vestrae.',
        14: 'Quia haec dicit Dominus exercituum: Sicut cogitavi ut affligerem vos, cum ad iracundiam provocassent patres vestri me, dicit Dominus,',
        15: 'et non sum misertus: sic conversus cogitavi in diebus istis ut benefaciam domui Iuda, et Ierusalem: nolite timere.',
        16: 'Haec sunt ergo verba, quae facietis: Loquimini veritatem, unusquisque cum proximo suo: veritatem, et iudicium pacis iudicate in portis vestris.',
        17: 'Et unusquisque malum contra amicum suum ne cogitetis in cordibus vestris: et iuramentum mendax ne diligatis: omnia enim haec sunt, quae odi, dicit Dominus.',
        18: 'Et factum est verbum Domini exercituum ad me, dicens:',
        19: 'Haec dicit Dominus exercituum: Ieiunium quarti, et ieiunium quinti, et ieiunium septimi, et ieiunium decimi erit domui Iuda in gaudium, et laetitiam, et in sollemnitates praeclaras: veritatem tantum, et pacem diligite.',
        20: 'Haec dicit Dominus exercituum: Usquequo veniant populi, et habitent in civitatibus multis,',
        21: 'et vadant habitatores, unus ad alterum, dicentes: Eamus, et deprecemur faciem Domini, et quaeramus Dominum exercituum: vadam etiam ego.',
        22: 'Et venient populi multi, et gentes robustae ad quaerendum Dominum exercituum in Ierusalem, et deprecandam faciem Domini.',
        23: 'Haec dicit Dominus exercituum: In diebus illis, in quibus apprehendent decem homines ex omnibus linguis Gentium, et apprehendent fimbriam viri Iudaei, dicentes: Ibimus vobiscum: audivimus enim quoniam Deus vobiscum est.',
    },
    9: {
        1: 'Onus verbi Domini in terra Hadrach, et Damasci requiei eius: quia Domini est oculus hominis, et omnium tribuum Israel.',
        2: 'Emath quoque in terminis eius, et Tyrus, et Sidon: assumpserunt quippe sibi sapientiam valde.',
        3: 'Et aedificavit Tyrus munitionem suam, et coacervavit argentum quasi humum, et aurum ut lutum platearum.',
        4: 'Ecce Dominus possidebit eam, et percutiet in mari fortitudinem eius, et haec igne devorabitur.',
        5: 'Videbit Ascalon, et timebit: et Gaza, et dolebit nimis: et Accaron, quoniam confusa est spes eius: et peribit rex de Gaza, et Ascalon non habitabitur.',
        6: 'Et sedebit separator in Azoto, et disperdam superbiam Philisthinorum.',
        7: 'Et auferam sanguinem eius de ore eius, et abominationes eius de medio dentium eius, et relinquetur etiam ipse Deo nostro, et erit quasi dux in Iuda, et Accaron quasi Iebusaeus.',
        8: 'Et circumdabo domum meam ex his, qui militant mihi euntes et revertentes, et non transibit super eos ultra exactor: quia nunc vidi in oculis meis.',
        9: 'Exulta satis filia Sion, iubila filia Ierusalem: ECCE REX TUUS veniet tibi iustus, et salvator: ipse pauper, et ascendens super asinam, et super pullum filium asinae.',
        10: 'Et disperdam quadrigam ex Ephraim, et equum de Ierusalem, et dissipabitur arcus belli: et loquetur pacem Gentibus, et potestas eius a mari usque ad mare, et a fluminibus usque ad fines terrae.',
        11: 'Tu quoque in sanguine testamenti tui emisisti vinctos tuos de lacu, in quo non est aqua.',
        12: 'Convertimini ad munitionem vincti spei, hodie quoque annuncians duplicia reddam tibi.',
        13: 'Quoniam extendi mihi Iuda quasi arcum, implevi Ephraim: et suscitabo filios tuos Sion super filios tuos Graecia: et ponam te quasi gladium fortium.',
        14: 'Et Dominus Deus super eos videbitur, et exibit ut fulgur, iaculum eius: et Dominus Deus in tuba canet, et vadet in turbine Austri.',
        15: 'Dominus exercituum proteget eos: et devorabunt, et subiicient lapidibus fundae: et bibentes inebriabuntur quasi a vino, et replebuntur ut phialae, et quasi cornua altaris.',
        16: 'Et salvabit eos Dominus Deus eorum in die illa, ut gregem populi sui: quia lapides sancti elevabuntur super terram eius.',
        17: 'Quid enim bonum eius est, et quid pulchrum eius, nisi frumentum electorum, et vinum germinans virgines?',
    },
    10: {
        1: 'Petite a Domino pluviam in tempore serotino, et Dominus faciet nives, et pluviam imbris dabit eis, singulis herbam in agro.',
        2: 'Quia simulacra locuta sunt inutile, et divini viderunt mendacium, et somniatores locuti sunt frustra: et vane consolabantur: idcirco abducti sunt quasi grex: affligentur, quia non est eis pastor.',
        3: 'Super pastores iratus est furor meus, et super hircos visitabo: quia visitavit Dominus exercituum gregem suum, domum Iuda, et posuit eos quasi equum gloriae suae in bello.',
        4: 'Ex ipso angulus, ex ipso paxillus, ex ipso arcus praelii, ex ipso egredietur omnis exactor simul.',
        5: 'Et erunt quasi fortes conculcantes lutum viarum in praelio: et bellabunt, quia Dominus cum eis: et confundentur ascensores equorum.',
        6: 'Et confortabo domum Iuda, et domum Ioseph salvabo: et convertam eos, quia miserebor eorum: et erunt sicut fuerunt quando non proieceram eos: ego enim Dominus Deus eorum, et exaudiam eos.',
        7: 'Et erunt quasi fortes Ephraim, et laetabitur cor eorum quasi a vino: et filii eorum videbunt, et laetabuntur, et exultabit cor eorum in Domino.',
        8: 'Sibilabo eis, et congregabo illos, quia redemi eos: et multiplicabo eos sicut ante fuerant multiplicati.',
        9: 'Et seminabo eos in populis, et de longe recordabuntur mei: et vivent cum filiis suis, et revertentur.',
        10: 'Et reducam eos de Terra Aegypti, et de Assyriis congregabo eos, et ad Terram Galaad et Libani adducam eos, et non invenietur eis locus:',
        11: 'et transibit in maris freto, et percutiet in mari fluctus, et confundentur omnia profunda fluminis, et humiliabitur superbia Assur, et sceptrum Aegypti recedet.',
        12: 'Confortabo eos in Domino, et in nomine eius ambulabunt, dicit Dominus.',
    },
    11: {
        1: 'Aperi Libane portas tuas, et comedat ignis cedros tuas.',
        2: 'Ulula abies, quia cecidit cedrus, quoniam magnifici vastati sunt: ululate quercus Basan, quoniam succisus est saltus munitus.',
        3: 'Vox ululatus pastorum, quia vastata est magnificentia eorum: vox rugitus leonum, quoniam vastata est superbia Iordanis.',
        4: 'Haec dicit Dominus Deus meus: Pasce pecora occisionis,',
        5: 'quae qui possederant, occidebant, et non dolebant, et vendebant ea, dicentes: Benedictus Dominus, divites facti sumus: et pastores eorum non parcebant eis.',
        6: 'Et ego non parcam ultra super habitantes terram, dicit Dominus: ecce ego tradam homines, unumquemque in manu proximi sui, et in manu regis sui: et concident terram, et non eruam de manu eorum.',
        7: 'Et pascam pecus occisionis propter hoc, o pauperes gregis: et assumpsi mihi duas virgas, unam vocavi Decorem, et alteram vocavi Funiculum: et pavi gregem.',
        8: 'Et succidi tres pastores in mense uno, et contracta est anima mea in eis: siquidem et anima eorum variavit in me.',
        9: 'Et dixi: Non pascam vos: quod moritur, moriatur: et quod succiditur, succidatur: et reliqui devorent unusquisque carnem proximi sui.',
        10: 'Et tuli virgam meam, quae vocabatur Decus, et abscidi eam ut irritum facerem foedus meum, quod percussi cum omnibus populis.',
        11: 'Et in irritum deductum est in die illa: et cognoverunt sic pauperes gregis, qui custodiunt mihi, quia verbum Domini est.',
        12: 'Et dixi ad eos: Si bonum est in oculis vestris, afferte mercedem meam: et si non, quiescite. Et appenderunt mercedem meam triginta argenteos.',
        13: 'Et dixit Dominus ad me: Proiice illud ad statuarium, decorum pretium, quo appretiatus sum ab eis. Et tuli triginta argenteos: et proieci illos in domum Domini ad statuarium.',
        14: 'Et praecidi virgam meam secundam, quae appellabatur Funiculus, ut dissolverem germanitatem inter Iuda, et Israel.',
        15: 'Et dixit Dominus ad me: Adhuc sume tibi vasa pastoris stulti.',
        16: 'Quia ecce ego suscitabo pastorem in terra, qui derelicta non visitabit, dispersum non quaeret, et contritum non sanabit, et id quod stat non enutriet, et carnes pinguium comedet, et ungulas eorum dissolvet.',
        17: 'O pastor, et idolum, derelinquens gregem: gladius super brachium eius, et super oculum dextrum eius: brachium eius ariditate siccabitur, et oculus dexter eius tenebrescens obscurabitur.',
    },
    12: {
        1: 'Onus verbi Domini super Israel. Dicit Dominus extendens caelum, et fundans terram, et fingens spiritum hominis in eo:',
        2: 'Ecce ego ponam Ierusalem superliminare crapulae omnibus populis in circuitu: sed et Iuda erit in obsidione contra Ierusalem.',
        3: 'Et erit: In die illa ponam Ierusalem lapidem oneris cunctis populis: omnes, qui levabunt eum, concisione lacerabuntur: et colligentur adversus eam omnia regna terrae.',
        4: 'In die illa, dicit Dominus, percutiam omnem equum in stuporem, et ascensorem eius in amentiam: et super domum Iuda aperiam oculos meos, et omnem equum populorum percutiam caecitate.',
        5: 'Et dicent duces Iuda in corde suo: Confortentur mihi habitatores Ierusalem in Domino exercituum Deo eorum.',
        6: 'In die illa ponam duces Iuda sicut caminum ignis in lignis, et sicut faciem ignis in foeno: et devorabunt ad dexteram, et ad sinistram omnes populos in circuitu: et habitabitur Ierusalem rursus in loco suo in Ierusalem.',
        7: 'Et salvabit Dominus tabernacula Iuda, sicut in principio: ut non magnifice glorietur domus David, et gloria habitantium Ierusalem contra Iuda.',
        8: 'In die illa proteget Dominus habitatores Ierusalem, et erit qui offenderit ex eis in die illa, quasi David: et domus David quasi Dei, sicut angelus Domini in conspectu eorum.',
        9: 'Et erit in die illa: quaeram conterere omnes Gentes, quae veniunt contra Ierusalem.',
        10: 'Et effundam super domum David, et super habitatores Ierusalem spiritum gratiae, et precum: et aspicient ad me, quem confixerunt: et plangent eum planctu quasi super unigenitum, et dolebunt super eum, ut doleri solet in morte primogeniti.',
        11: 'In die illa magnus erit planctus in Ierusalem, sicut planctus Adadremmon in campo Mageddon.',
        12: 'Et planget terra: familiae et familiae seorsum: familiae domus David seorsum, et mulieres eorum seorsum:',
        13: 'familiae domus Nathan seorsum, et mulieres eorum seorsum: familiae domus Levi seorsum, et mulieres eorum seorsum: familiae Semei seorsum, et mulieres eorum seorsum.',
        14: 'Omnes familiae reliquae, familiae et familiae seorsum, et mulieres eorum seorsum.',
    },
    13: {
        1: 'In die illa erit fons patens domui David, et habitantibus Ierusalem in ablutionem peccatoris et menstruatae.',
        2: 'Et erit in die illa, dicit Dominus exercituum: Disperdam nomina idolorum de terra, et non memorabuntur ultra: et pseudoprophetas, et spiritum immundum auferam de terra.',
        3: 'Et erit, cum prophetaverit quispiam ultra, dicent ei pater eius, et mater eius, qui genuerunt eum: Non vives: quia mendacium locutus es in nomine Domini. et configent eum pater eius, et mater eius, genitores eius, cum prophetaverit.',
        4: 'Et erit: In die illa confundentur prophetae, unusquisque ex visione sua cum prophetaverit: nec operientur pallio saccino, ut mentiantur:',
        5: 'sed dicet: Non sum propheta, homo agricola ego sum: quoniam Adam exemplum meum ab adolescentia mea.',
        6: 'Et dicetur ei: Quid sunt plagae istae in medio manuum tuarum? Et dicet: His plagatus sum in domo eorum, qui diligebant me.',
        7: 'Framea suscitare super pastorem meum, et super virum cohaerentem mihi, dicit Dominus exercituum: percute pastorem, et dispergentur oves: et convertam manum meam ad parvulos.',
        8: 'Et erunt in omni terra, dicit Dominus: partes duae in ea dispergentur, et deficient: et tertia pars relinquetur in ea.',
        9: 'Et ducam tertiam partem per ignem, et uram eos sicut uritur argentum: et probabo eos sicut probatur aurum. Ipse vocabit nomen meum, et ego exaudiam eum. Et dicam: Populus meus es; et ipse dicet: Dominus Deus meus.',
    },
    14: {
        1: 'Ecce venient dies Domini, et dividentur spolia tua in medio tui.',
        2: 'Et congregabo omnes Gentes ad Ierusalem in praelium, et capietur civitas, et vastabuntur domus, et mulieres violabuntur: et egredietur media pars civitatis in captivitatem, et reliquum populi non auferetur ex urbe.',
        3: 'Et egredietur Dominus, et praeliabitur contra Gentes illas, sicut praeliatus est in die certaminis.',
        4: 'Et stabunt pedes eius in die illa super Montem olivarum, qui est contra Ierusalem ad Orientem: et scindetur Mons olivarum ex media parte sui ad Orientem, et ad Occidentem praerupto grandi valde, et separabitur medium montis ad Aquilonem, et medium eius ad Meridiem.',
        5: 'Et fugietis ad vallem montium eorum, quoniam coniungetur vallis montium usque ad proximum: et fugietis sicut fugistis a facie terraemotus in diebus Oziae regis Iuda: et veniet Dominus Deus meus, omnesque sancti cum eo.',
        6: 'Et erit in die illa: Non erit lux, sed frigus et gelu.',
        7: 'Et erit dies una, quae nota est Domino, non dies neque nox: et in tempore vesperi erit lux.',
        8: 'Et erit in die illa: Exibunt aquae vivae de Ierusalem: medium earum ad mare Orientale, et medium earum ad mare novissimum: in aestate et in hieme erunt.',
        9: 'Et erit Dominus Rex super omnem terram: in die illa erit Dominus unus, et erit nomen eius unum.',
        10: 'Et revertetur omnis terra usque ad desertum, de colle Remmon ad Austrum Ierusalem: et exaltabitur, et habitabitur in loco suo a porta Beniamin usque ad locum portae prioris, et usque ad portam angulorum: et a turre Hananeel usque ad torcularia regis.',
        11: 'Et habitabunt in ea, et anathema non erit amplius: sed sedebit Ierusalem secura.',
        12: 'Et haec erit plaga, qua percutiet Dominus omnes Gentes, quae pugnaverunt adversus Ierusalem: Tabescet caro uniuscuiusque stantis super pedes suos, et oculi eius contabescent in foraminibus suis, et lingua eorum contabescet in ore suo.',
        13: 'In die illa erit tumultus Domini magnus in eis: et apprehendet vir manum proximi sui, et conseretur manus eius super manum proximi sui.',
        14: 'Sed et Iuda pugnabit adversus Ierusalem: et congregabuntur divitiae omnium Gentium in circuitu, aurum, et argentum, et vestes multae satis.',
        15: 'Et sic erit ruina equi, et muli, et cameli, et asini, et omnium iumentorum, quae fuerint in castris illis, sicut ruina haec.',
        16: 'Et omnes, qui reliqui fuerint de universis Gentibus, quae venerunt contra Ierusalem, ascendent ab anno in annum, ut adorent Regem, Dominum exercituum, et celebrent festivitatem tabernaculorum.',
        17: 'Et erit: Qui non ascenderit de familiis terrae ad Ierusalem, ut adoret Regem, Dominum exercituum, non erit super eos imber.',
        18: 'Quod et si familia Aegypti non ascenderit, et non venerit: nec super eos erit, sed erit ruina, qua percutiet Dominus omnes Gentes, quae non ascenderint ad celebrandam festivitatem tabernaculorum.',
        19: 'Hoc erit peccatum Aegypti, et hoc peccatum omnium Gentium, quae non ascenderint ad celebrandam festivitatem tabernaculorum.',
        20: 'In die illa erit quod super frenum equi est, sanctum Domino: et erunt lebetes in domo Domini quasi phialae coram altari.',
        21: 'Et erit omnis lebes in Ierusalem, et in Iuda sanctificatus Domino exercituum: et venient omnes immolantes, et sument ex eis, et coquent in eis: et non erit mercator ultra in domo Domini exercituum in die illo.',
    },
}
